import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

test('totals tool rounds separately for each message (specs/hal-engine-usage-totals/spec.md#2)', async () => {
  const rounds: MessageChunk[][] = [
    [
      {type: 'tool_use', toolCall: {id: 'lookup', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 3, totalTokens: 5}},
    ],
    [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 11, totalTokens: 18}}],
    [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 13, outputTokens: 17, totalTokens: 30}}],
  ];
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds.shift() ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      throw new Error('This contract only uses streaming responses.');
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
  const reports: Array<UsageMetadata | undefined> = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage contract'}), registry, {
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    },
  });
  const session: ChatSession = {sessionId: 'session', userId: 'user', entries: []};

  await orchestrator.processMessage(session);
  await orchestrator.processMessage(session);

  expect(reports).toEqual([
    {inputTokens: 9, outputTokens: 14, totalTokens: 23},
    {inputTokens: 13, outputTokens: 17, totalTokens: 30},
  ]);
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/turnUsage.test.ts --runInBand"
